    "\u7ed9\u4f60\u4e00\u4e2a\u5076\u6570 n\u200b\u200b\u200b\u200b\u200b\u200b \uff0c\u5df2\u77e5\u5b58\u5728\u4e00\u4e2a\u957f\u5ea6\u4e3a n \u7684\u6392\u5217 perm \uff0c\u5176\u4e2d perm[i] == i\u200b\uff08\u4e0b\u6807 \u4ece 0 \u5f00\u59cb \u8ba1\u6570\uff09\u3002\n\n\u4e00\u6b65\u64cd\u4f5c\u4e2d\uff0c\u4f60\u5c06\u521b\u5efa\u4e00\u4e2a\u65b0\u6570\u7ec4 arr \uff0c\u5bf9\u4e8e\u6bcf\u4e2a i \uff1a\n\n\t\u5982\u679c i % 2 == 0 \uff0c\u90a3\u4e48 arr[i] = perm[i / 2]\n\n\t\u5982\u679c i % 2 == 1 \uff0c\u90a3\u4e48 arr[i] = perm[n / 2 + (i - 1) / 2]\n\n\u7136\u540e\u5c06 arr\u200b\u200b \u8d4b\u503c\u200b\u200b\u7ed9 perm \u3002\n\n\u8981\u60f3\u4f7f perm \u56de\u5230\u6392\u5217\u521d\u59cb\u503c\uff0c\u81f3\u5c11\u9700\u8981\u6267\u884c\u591a\u5c11\u6b65\u64cd\u4f5c\uff1f\u8fd4\u56de\u6700\u5c0f\u7684 \u975e\u96f6 \u64cd\u4f5c\u6b65\u6570\u3002\n\n\u00a0\n\n\u793a\u4f8b 1\uff1a\n\n```\n\u8f93\u5165\uff1an = 2\n\u8f93\u51fa\uff1a1\n\u89e3\u91ca\uff1a\u6700\u521d\uff0cperm = [0,1]\n\u7b2c 1\u00a0\u6b65\u64cd\u4f5c\u540e\uff0cperm = [0,1]\n\u6240\u4ee5\uff0c\u4ec5\u9700\u6267\u884c 1 \u6b65\u64cd\u4f5c\n```\n\n\u793a\u4f8b 2\uff1a\n\n```\n\u8f93\u5165\uff1an = 4\n\u8f93\u51fa\uff1a2\n\u89e3\u91ca\uff1a\u6700\u521d\uff0cperm = [0,1,2,3]\n\u7b2c 1\u00a0\u6b65\u64cd\u4f5c\u540e\uff0cperm = [0,2,1,3]\n\u7b2c 2\u00a0\u6b65\u64cd\u4f5c\u540e\uff0cperm = [0,1,2,3]\n\u6240\u4ee5\uff0c\u4ec5\u9700\u6267\u884c 2 \u6b65\u64cd\u4f5c\n```\n\n\u793a\u4f8b 3\uff1a\n\n```\n\u8f93\u5165\uff1an = 6\n\u8f93\u51fa\uff1a4\n```\n\n\u00a0\n\n\u63d0\u793a\uff1a\n\n\t2\n\n\tn\u200b\u200b\u200b\u200b\u200b\u200b \u662f\u4e00\u4e2a\u5076\u6570",
    "\u6bcf\u884c\u4e00\u4e2a\u53c2\u6570\uff08JSON \u683c\u5f0f\uff09\uff0c\u4f9d\u6b21\u4e3a\uff1an\u3002",
    "\u8f93\u51fa integer \u7c7b\u578b\u7ed3\u679c\uff08JSON \u5e8f\u5217\u5316\uff09\u3002",
    "",
    "import sys, json\nimport itertools, functools, collections, math, bisect, string, heapq, random, operator\nfrom typing import *\nfrom collections import *\nfrom itertools import *\nfrom bisect import *\nfrom functools import *\nfrom math import *\nfrom string import *\nfrom operator import *\n\nclass Solution:\n    def reinitializePermutation(self, n: int) -> int:\n        perm = list(range(n))\n        target = perm.copy()\n        step = 0\n        while True:\n            step += 1\n            perm = [perm[n // 2 + (i - 1) // 2] if i % 2 else perm[i // 2] for i in range(n)]\n            if perm == target:\n                return step\n\ndef main():\n    _dec = json.JSONDecoder()\n    _text = sys.stdin.read()\n    _idx = 0\n    _args = []\n    while _idx < len(_text):\n        while _idx < len(_text) and _text[_idx] in ' \\t\\r\\n':\n            _idx += 1\n        if _idx >= len(_text):\n            break\n        try:\n            _obj, _end = _dec.raw_decode(_text, _idx)\n            _args.append(_obj)\n            _idx = _end\n        except Exception:\n            _nl = _text.find('\\n', _idx)\n            if _nl == -1:\n                _idx = len(_text)\n            else:\n                _idx = _nl + 1\n    _sol = Solution()\n\n    _ret = _sol.reinitializePermutation(_args[0])\n    if _ret is None:\n        _out = ''\n    elif isinstance(_ret, (list, dict)):\n        _out = json.dumps(_ret, separators=(',', ':'))\n    elif isinstance(_ret, bool):\n        _out = 'true' if _ret else 'false'\n    elif isinstance(_ret, float):\n        _out = repr(_ret)\n    else:\n        _out = str(_ret)\n    sys.stdout.write(_out)\n\nmain()\n",
